const $ = (selector) => document.querySelector(selector);
const canvas = $('#art');
const ctx = canvas.getContext('2d');
const palettes = {lilac:{name:'Lilac dusk',bg:'#d5c5f5',ink:'#343044',accent:'#d9ed89'},citrus:{name:'Acid garden',bg:'#d9ed89',ink:'#303629',accent:'#c3b0ea'},peach:{name:'Pumpkin hour',bg:'#f6b68e',ink:'#573a36',accent:'#dad1f1'},night:{name:'Midnight club',bg:'#303143',ink:'#ede4ff',accent:'#d9ed89'}};
const names = {ghost:'Little ghost',pumpkin:'Odd pumpkin',cat:'Night cat',bat:'Baby bat',photo:'Your photo'};
const defaults = {character:'ghost',palette:'lilac',message:'Too cute to spook.',lettering:'bold',scale:100,rotation:-8,transparent:false,touches:['sparkles'],photo:null};
let state = structuredClone(defaults), photo = null, history = [structuredClone(defaults)], cursor = 0, uploadSequence = 0;
const message = (text, error=false) => { $('#status').textContent=text; $('#status').classList.toggle('error',error); };
function path(c, fill, stroke, width, draw) { c.beginPath();draw(c);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.lineJoin='round';c.lineCap='round';c.stroke();} }
function ellipse(c,x,y,rx,ry,color){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=color;c.fill();}
function ghost(c){path(c,'#fffdf4','#322e3e',5,p=>{p.moveTo(-185,210);p.bezierCurveTo(-160,115,-210,5,-170,-120);p.bezierCurveTo(-125,-292,125,-292,170,-120);p.bezierCurveTo(205,0,165,100,205,195);p.quadraticCurveTo(145,165,115,218);p.quadraticCurveTo(65,160,15,220);p.quadraticCurveTo(-40,166,-90,220);p.quadraticCurveTo(-140,170,-185,210);});ellipse(c,-61,-28,18,29,'#322e3e');ellipse(c,61,-28,18,29,'#322e3e');ellipse(c,0,43,19,24,'#322e3e');ellipse(c,-109,17,29,15,'#efaea2');ellipse(c,109,17,29,15,'#efaea2');path(c,null,'#322e3e',4,p=>{p.moveTo(-133,66);p.quadraticCurveTo(-109,36,-88,70);p.moveTo(100,75);p.quadraticCurveTo(122,47,143,74);});}
function pumpkin(c){path(c,'#617253','#322e3e',5,p=>{p.moveTo(-14,-180);p.lineTo(-1,-265);p.quadraticCurveTo(43,-280,56,-250);p.lineTo(26,-175);p.closePath();});ellipse(c,-93,22,125,190,'#f4a362');ellipse(c,94,22,125,190,'#ed9657');ellipse(c,0,22,141,205,'#ffb56e');path(c,null,'#c37946',4,p=>{p.moveTo(-63,-153);p.bezierCurveTo(-145,-11,-133,113,-60,197);p.moveTo(65,-153);p.bezierCurveTo(146,-11,132,113,60,197);});ellipse(c,-67,-15,17,24,'#3d3036');ellipse(c,67,-15,17,24,'#3d3036');path(c,'#3d3036',null,0,p=>{p.moveTo(-63,68);p.quadraticCurveTo(0,135,63,68);p.quadraticCurveTo(0,104,-63,68);});ellipse(c,-116,38,25,12,'#db7c58');ellipse(c,116,38,25,12,'#db7c58');}
function cat(c){path(c,'#38343d','#fff9eb',7,p=>{p.moveTo(-164,110);p.bezierCurveTo(-185,8,-150,-75,-145,-104);p.lineTo(-171,-220);p.lineTo(-63,-167);p.quadraticCurveTo(0,-190,69,-167);p.lineTo(175,-220);p.lineTo(150,-87);p.bezierCurveTo(204,57,153,169,0,175);p.quadraticCurveTo(-116,182,-164,110);});path(c,'#c6ade6',null,0,p=>{p.moveTo(-143,-182);p.lineTo(-127,-106);p.lineTo(-83,-150);p.closePath();p.moveTo(143,-182);p.lineTo(127,-106);p.lineTo(83,-150);p.closePath();});ellipse(c,-66,-19,35,28,'#d9ed89');ellipse(c,66,-19,35,28,'#d9ed89');ellipse(c,-62,-19,8,25,'#38343d');ellipse(c,62,-19,8,25,'#38343d');path(c,'#f3b7ab',null,0,p=>{p.moveTo(-15,32);p.lineTo(15,32);p.lineTo(0,46);p.closePath();});path(c,null,'#f5ebdf',4,p=>{p.moveTo(0,46);p.quadraticCurveTo(-10,70,-27,55);p.moveTo(0,46);p.quadraticCurveTo(10,70,27,55);p.moveTo(-84,50);p.lineTo(-183,26);p.moveTo(-85,72);p.lineTo(-184,88);p.moveTo(84,50);p.lineTo(183,26);p.moveTo(85,72);p.lineTo(184,88);});}
function bat(c){path(c,'#9a8ac3','#393442',6,p=>{p.moveTo(-55,-48);p.quadraticCurveTo(-180,-170,-267,-135);p.quadraticCurveTo(-246,-30,-260,65);p.quadraticCurveTo(-195,-1,-155,91);p.quadraticCurveTo(-118,31,-57,109);p.lineTo(57,109);p.quadraticCurveTo(118,31,155,91);p.quadraticCurveTo(195,-1,260,65);p.quadraticCurveTo(246,-30,267,-135);p.quadraticCurveTo(180,-170,55,-48);p.closePath();});path(c,'#635778','#fff6e8',6,p=>{p.moveTo(-72,-60);p.lineTo(-89,-159);p.lineTo(-30,-112);p.quadraticCurveTo(0,-127,30,-112);p.lineTo(89,-159);p.lineTo(72,-60);p.bezierCurveTo(160,148,-160,148,-72,-60);});ellipse(c,-33,-14,11,18,'#fff8eb');ellipse(c,33,-14,11,18,'#fff8eb');path(c,'#fff8eb',null,0,p=>{p.moveTo(-24,31);p.lineTo(-12,55);p.lineTo(0,35);p.lineTo(12,55);p.lineTo(24,31);p.closePath();});}
const characters = {ghost,pumpkin,cat,bat};
function sparkle(c,x,y,size,color,rotation=0){c.save();c.translate(x,y);c.rotate(rotation);path(c,color,null,0,p=>{p.moveTo(0,-size);p.quadraticCurveTo(size*.15,-size*.15,size,0);p.quadraticCurveTo(size*.15,size*.15,0,size);p.quadraticCurveTo(-size*.15,size*.15,-size,0);p.quadraticCurveTo(-size*.15,-size*.15,0,-size);});c.restore();}
function star(c,x,y,r,color){path(c,color,null,0,p=>{for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.45:r;let x1=x+Math.cos(a)*rr,y1=y+Math.sin(a)*rr;i?p.lineTo(x1,y1):p.moveTo(x1,y1);}p.closePath();});}
function drawCharacter(c, kind, scale=1){c.save();c.scale(scale,scale);characters[kind]?.(c);c.restore();}
function render(){const p=palettes[state.palette];ctx.clearRect(0,0,1200,1200);if(!state.transparent){ctx.fillStyle=p.bg;ctx.fillRect(0,0,1200,1200);ctx.strokeStyle=p.ink+'16';ctx.lineWidth=2;for(let i=42;i<1200;i+=60){for(let j=42;j<1200;j+=60){ctx.beginPath();ctx.arc(i,j,1.5,0,Math.PI*2);ctx.stroke();}}}ctx.save();ctx.translate(600,535);ctx.rotate(state.rotation*Math.PI/180);ctx.scale(state.scale/100,state.scale/100);ctx.shadowColor='#26212f22';ctx.shadowBlur=24;ctx.shadowOffsetY=18;if(state.character==='photo'&&photo){const size=490,ratio=Math.min(size/photo.naturalWidth,size/photo.naturalHeight);ctx.fillStyle='#fffaf0';ctx.rotate(.03);ctx.fillRect(-278,-278,556,556);ctx.shadowColor='transparent';ctx.drawImage(photo,-photo.naturalWidth*ratio/2,-photo.naturalHeight*ratio/2,photo.naturalWidth*ratio,photo.naturalHeight*ratio);ctx.fillStyle='#36313f';ctx.font='14px monospace';ctx.textAlign='center';ctx.fillText('A LITTLE MOMENT OF MISCHIEF',0,266);}else{drawCharacter(ctx,state.character,1.15);}ctx.restore();if(state.touches.includes('sparkles')){sparkle(ctx,228,250,62,p.ink,-.2);sparkle(ctx,984,630,54,p.ink,.1);sparkle(ctx,931,245,28,p.ink);sparkle(ctx,240,736,25,p.ink);}if(state.touches.includes('stars')){star(ctx,944,352,54,p.accent);star(ctx,266,606,45,p.accent);star(ctx,933,759,26,p.accent);}if(state.touches.includes('dots')){[[202,458],[1010,440],[344,220],[834,814],[343,833],[1011,812],[203,851]].forEach(([x,y],i)=>ellipse(ctx,x,y,9+i%3*3,9+i%3*3,p.ink));}ctx.fillStyle=p.ink;ctx.textAlign='center';ctx.font='17px monospace';ctx.letterSpacing='4px';ctx.fillText('THE AFTER HOURS CLUB',600,121);ctx.letterSpacing='0px';const family=state.lettering==='serif'?'Georgia, serif':state.lettering==='mono'?'monospace':'Arial, sans-serif';let fontSize=state.lettering==='mono'?72:87;ctx.font=`${state.lettering==='bold'?'900':'500'} ${fontSize}px ${family}`;while(ctx.measureText(state.message).width>1000&&fontSize>24){fontSize-=2;ctx.font=`${state.lettering==='bold'?'900':'500'} ${fontSize}px ${family}`;}ctx.fillText(state.message,600,975);ctx.strokeStyle=p.ink;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(440,1043);ctx.lineTo(760,1043);ctx.stroke();ctx.font='15px monospace';ctx.fillText('MADE OF A LITTLE MAGIC',600,1093);}
function sync(){document.querySelectorAll('[data-character]').forEach(b=>{const active=b.dataset.character===state.character;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active);});document.querySelectorAll('[data-palette]').forEach(b=>{const active=b.dataset.palette===state.palette;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});document.querySelectorAll('[data-touch]').forEach(b=>{const active=state.touches.includes(b.dataset.touch);b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);b.querySelector('i').textContent=active?'✓':'+';});for(const key of ['message','lettering','scale','rotation'])$('#'+key).value=state[key];$('#transparent').checked=state.transparent;$('#scale-value').value=state.scale+'%';$('#rotation-value').value=state.rotation+'°';$('#palette-name').textContent=palettes[state.palette].name;$('#character-name').textContent=names[state.character].toUpperCase();$('#count').textContent=state.message.length+' / 28';$('#undo').disabled=cursor===0;$('#redo').disabled=cursor===history.length-1;render();}
function commit(){const snapshot=structuredClone(state);if(JSON.stringify(snapshot)===JSON.stringify(history[cursor]))return;history=history.slice(0,cursor+1);history.push(snapshot);if(history.length>30)history.shift();cursor=history.length-1;sync();}
function change(key,value){state[key]=value;commit();}
async function decodeImage(source){const image=new Image();image.src=source;await image.decode();return image;}
async function applySnapshot(snapshot){const token=++uploadSequence;try{const loaded=snapshot.photo?await decodeImage(snapshot.photo):null;if(token!==uploadSequence)return;photo=loaded;state=structuredClone(snapshot);sync();}catch{message('This image could not be restored. Choose a new photo.',true);}}
document.querySelectorAll('[data-character]').forEach(b=>b.addEventListener('click',()=>change('character',b.dataset.character)));
document.querySelectorAll('[data-palette]').forEach(b=>b.addEventListener('click',()=>change('palette',b.dataset.palette)));
document.querySelectorAll('[data-touch]').forEach(b=>b.addEventListener('click',()=>{const t=b.dataset.touch;state.touches=state.touches.includes(t)?state.touches.filter(x=>x!==t):[...state.touches,t];commit();}));
$('#message').addEventListener('input',e=>change('message',e.target.value));$('#lettering').addEventListener('change',e=>change('lettering',e.target.value));for(const key of ['scale','rotation'])$('#'+key).addEventListener('input',e=>change(key,Number(e.target.value)));$('#transparent').addEventListener('change',e=>change('transparent',e.target.checked));
$('#undo').addEventListener('click',()=>{if(cursor>0)applySnapshot(history[--cursor]);});$('#redo').addEventListener('click',()=>{if(cursor<history.length-1)applySnapshot(history[++cursor]);});
document.addEventListener('keydown',e=>{const t=e.target;if(t.isContentEditable||['INPUT','TEXTAREA','SELECT'].includes(t.tagName))return;const mac=e.metaKey,ctrl=e.ctrlKey,key=e.key.toLowerCase();if(!(mac||ctrl))return;if(key==='z'&&!e.shiftKey){e.preventDefault();if(cursor>0)applySnapshot(history[--cursor]);}else if((key==='z'&&e.shiftKey)||(ctrl&&key==='y')){e.preventDefault();if(cursor<history.length-1)applySnapshot(history[++cursor]);}});
$('#reset').addEventListener('click',()=>{uploadSequence++;photo=null;state=structuredClone(defaults);$('#file').value='';commit();message('A fresh start. Make something wonderfully weird.');});
$('#file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){message('Choose a PNG, JPG or WebP image.',true);e.target.value='';return;}if(file.size>10*1024*1024){message('That image is a little big. Choose one under 10 MB.',true);e.target.value='';return;}const token=++uploadSequence;message('Getting your photo ready…');try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const loaded=await decodeImage(data);if(token!==uploadSequence)return;if(loaded.naturalWidth*loaded.naturalHeight>40000000)throw new Error('size');const resized=document.createElement('canvas');const factor=Math.min(1,1600/Math.max(loaded.naturalWidth,loaded.naturalHeight));resized.width=Math.round(loaded.naturalWidth*factor);resized.height=Math.round(loaded.naturalHeight*factor);resized.getContext('2d').drawImage(loaded,0,0,resized.width,resized.height);const normalized=resized.toDataURL('image/png');const decodedPhoto=await decodeImage(normalized);if(token!==uploadSequence)return;photo=decodedPhoto;state.photo=normalized;state.character='photo';commit();message('Your photo is ready. Add a little personality.');}catch{message('Could not open that image. Try a smaller, valid PNG, JPG or WebP.',true);}finally{e.target.value='';}});
$('#export').addEventListener('click',()=>{render();canvas.toBlob(blob=>{if(!blob){message('Export failed. Please try again.',true);return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`boo-studio-${state.character}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);message('Your PNG is ready. Check your browser downloads.');},'image/png');});
$('#save').addEventListener('click',()=>{try{localStorage.setItem('boo-studio-draft-v1',JSON.stringify({version:1,state}));message('Draft saved on this browser. Come back for more mischief.');}catch{message('Browser storage is full or unavailable. Export your sticker instead.',true);}});
function validDraft(value){const s=value?.state;return value?.version===1&&s&&(['ghost','pumpkin','cat','bat','photo'].includes(s.character))&&Object.hasOwn(palettes,s.palette)&&typeof s.message==='string'&&s.message.length<=28&&['bold','serif','mono'].includes(s.lettering)&&Number.isFinite(s.scale)&&s.scale>=65&&s.scale<=120&&Number.isFinite(s.rotation)&&s.rotation>=-25&&s.rotation<=25&&typeof s.transparent==='boolean'&&Array.isArray(s.touches)&&s.touches.every(x=>['sparkles','stars','dots'].includes(x))&&(s.photo===null||typeof s.photo==='string'&&s.photo.startsWith('data:image/png;base64,')&&s.photo.length<15000000)&&(s.character!=='photo'||s.photo);}
$('#restore').addEventListener('click',async()=>{try{const raw=localStorage.getItem('boo-studio-draft-v1');if(!raw){message('No saved draft yet. Use “Save a draft for later” first.');return;}const draft=JSON.parse(raw);if(!validDraft(draft))throw new Error('invalid');await applySnapshot(draft.state);commit();message('Your saved mischief is back.');}catch{message('This draft could not be restored. Start a fresh sticker.',true);}});
for(const thumb of document.querySelectorAll('[data-thumb]')){const c=thumb.getContext('2d');c.translate(60,62);drawCharacter(c,thumb.dataset.thumb,.19);}
sync();
